const fs = await import('node:fs/promises');
const S = "D:\\GitHub\\My-second-brain\\50-知识\\AI工具\\_scripts";
const M = JSON.parse(await fs.readFile(S+"\\_GIG_MASTER_FINAL.json","utf8"));

// 审计：哪些其实是「招聘板/找全职」而不是「接散活」
const JOBBOARD = ["dribbble.com","varsitytutors.com","wyzant.com","tutorhunt.com","preply.com","cambly.com","studypool.com","workingnotworking.com","99designs.com","designcrowd.com","glg.com","thirdbridge.com","tegus.com","zintro.com","ttec.com","arise.com","concentrix.com","streetbees.com","premise.com","prizerebel.com","figure-eight.com","bugbase.in","cobalt.io","synack.com","hackenproof.com"];

const all = [];
for (const [cat, items] of Object.entries(M.groups)) for (const it of items) all.push({...it, cat});

const audit = all.map(a=>{
  const h = String(a.host).toLowerCase();
  const isJobboard = JOBBOARD.includes(h);
  return { name:a.name, host:h, cat:a.cat, group:a.group, isJobboard, note:a.note };
});

// 分类：真散活 vs 可能是招聘
const gig = audit.filter(a=>!a.isJobboard);
const maybe = audit.filter(a=>a.isJobboard);

return {
  total: audit.length,
  pureGig: gig.length,
  needReview: maybe.length,
  reviewList: maybe.map(a=>a.name+" ("+a.cat+")")
};
